1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Damage {
14	  itemType: string;
15	  amount: number;
16	}
17	
18	export interface Incident {
19	  cause: string;
20	  damages: Damage[];
21	}
22	
23	export interface ClaimStep {
24	  op: "claim";
25	  /** Zero-based index of the quote step that created the policy. */
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export type Step = QuoteStep | ClaimStep;
31	
32	export interface Customer {
33	  yearsWithMHPCO: number;
34	}
35	
36	export interface Scenario {
37	  customer: Customer;
38	  steps: Step[];
39	}
40	
41	export interface QuoteResult {
42	  premium: number;
43	}
44	
45	export interface ClaimResult {
46	  payout: number;
47	  remainingCap: number;
48	}
49	
50	export interface ScenarioResults {
51	  results: (QuoteResult | ClaimResult)[];
52	}
53	
54	const PROCESSING_FEE = 5;
55	const FIRST_INSURANCE_SURCHARGE = 0.1;
56	const CURSE_SURCHARGE = 0.5;
57	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
58	const HIGH_ENCHANTMENT_THRESHOLD = 5;
59	const LOYALTY_DISCOUNT = 0.2;
60	const LOYALTY_THRESHOLD_YEARS = 2;
61	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
62	
63	/** Premiums are rounded up (in the MHPCO's favour), ignoring float noise. */
64	const roundUp = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
65	
66	interface ItemTariff {
67	  basePremium: number;
68	  insuranceValue: number;
69	}
70	
71	/** The known item types, with the two rates the tariff sets for each. */
72	const TARIFF: Record<string, ItemTariff> = {
73	  sword: { basePremium: 100, insuranceValue: 1000 },
74	  amulet: { basePremium: 60, insuranceValue: 600 },
75	  staff: { basePremium: 80, insuranceValue: 800 },
76	  potion: { basePremium: 40, insuranceValue: 400 },
77	  rune: { basePremium: 25, insuranceValue: 250 },
78	  moonstone: { basePremium: 25, insuranceValue: 250 },
79	};
80	
81	const DEDUCTIBLE = 100;
82	const CAP_MULTIPLIER = 2;
83	const STRONG_ENCHANTMENT_THRESHOLD = 8;
84	const STRONG_ENCHANTMENT_REIMBURSEMENT = 0.5;
85	
86	const COMPONENT_TYPES = ["rune", "moonstone"];
87	const BLOCK_SIZE = 3;
88	const BLOCK_BASE_PREMIUM = 60;
89	
90	const isComponent = (type: string): boolean => COMPONENT_TYPES.includes(type);
91	
92	const countByType = (items: Item[]): Map<string, number> => {
93	  const counts = new Map<string, number>();
94	
95	  for (const item of items) {
96	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
97	  }
98	
99	  return counts;
100	};
101	
102	/** Exactly BLOCK_SIZE alike components form a building block. */
103	const formsBuildingBlock = (type: string, count: number): boolean =>
104	  isComponent(type) && count === BLOCK_SIZE;
105	
106	const itemBasePremium = (type: string): number => TARIFF[type].basePremium;
107	
108	const itemInsuranceValue = (type: string): number => TARIFF[type].insuranceValue;
109	
110	/** Alike items are priced together so a building block can be recognised. */
111	const groupBasePremium = (type: string, count: number): number =>
112	  formsBuildingBlock(type, count)
113	    ? BLOCK_BASE_PREMIUM
114	    : count * itemBasePremium(type);
115	
116	/** The policy base premium is the sum of the base premiums of its items. */
117	const policyBasePremium = (items: Item[]): number =>
118	  [...countByType(items)].reduce(
119	    (total, [type, count]) => total + groupBasePremium(type, count),
120	    0,
121	  );
122	
123	const isCursed = (item: Item): boolean => item.cursed === true;
124	
125	const isHighlyEnchanted = (item: Item): boolean =>
126	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
127	
128	/**
129	 * Item-specific surcharges stack additively, as fractions of the item's base
130	 * premium.
131	 */
132	const itemSurchargeRate = (item: Item): number =>
133	  (isCursed(item) ? CURSE_SURCHARGE : 0) +
134	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
135	
136	/**
137	 * Item-specific modifiers apply to the base premium of the affected item,
138	 * not to the policy total.
139	 */
140	const itemSurcharges = (items: Item[]): number =>
141	  items.reduce(
142	    (total, item) =>
143	      total + itemBasePremium(item.type) * itemSurchargeRate(item),
144	    0,
145	  );
146	
147	const isLoyalCustomer = (customer: Customer): boolean =>
148	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
149	
150	/**
151	 * Policy-wide modifiers, as fractions of the policy base premium. Each is an
152	 * amount added to (or, when negative, subtracted from) that base premium, so
153	 * modifiers stack additively rather than compounding.
154	 */
155	const policyModifierRates = (
156	  customer: Customer,
157	  isFollowUpContract: boolean,
158	): number[] => [
159	  FIRST_INSURANCE_SURCHARGE,
160	  isLoyalCustomer(customer) ? -LOYALTY_DISCOUNT : 0,
161	  isFollowUpContract ? -FOLLOW_UP_CONTRACT_DISCOUNT : 0,
162	];
163	
164	const policyModifiers = (
165	  basePremium: number,
166	  customer: Customer,
167	  isFollowUpContract: boolean,
168	): number =>
169	  policyModifierRates(customer, isFollowUpContract).reduce(
170	    (total, rate) => total + basePremium * rate,
171	    0,
172	  );
173	
174	const quotePremium = (
175	  step: QuoteStep,
176	  customer: Customer,
177	  isFollowUpContract: boolean,
178	): number => {
179	  const basePremium = policyBasePremium(step.items);
180	
181	  return roundUp(
182	    basePremium +
183	      itemSurcharges(step.items) +
184	      policyModifiers(basePremium, customer, isFollowUpContract) +
185	      PROCESSING_FEE,
186	  );
187	};
188	
189	/**
190	 * Every contract after the customer's first is a follow-up. Only quote steps
191	 * create contracts, so this counts preceding quotes rather than preceding steps.
192	 */
193	const isFollowUpContract = (precedingSteps: Step[]): boolean =>
194	  precedingSteps.some((step) => step.op === "quote");
195	
196	/** Payouts are rounded down (in the MHPCO's favour), ignoring float noise. */
197	const roundDown = (amount: number): number =>
198	  Math.floor(Number(amount.toFixed(6)));
199	
200	/** The insurance sum is the sum of the items' insurance values. */
201	const insuranceSum = (items: Item[]): number =>
202	  items.reduce((total, item) => total + itemInsuranceValue(item.type), 0);
203	
204	const isStronglyEnchanted = (item: Item): boolean =>
205	  (item.enchantment ?? 0) >= STRONG_ENCHANTMENT_THRESHOLD;
206	
207	/**
208	 * The reimbursement clauses decide how much of the damage is reimbursed,
209	 * before the deductible is applied.
210	 */
211	const reimbursementRate = (item: Item): number =>
212	  isStronglyEnchanted(item) ? STRONG_ENCHANTMENT_REIMBURSEMENT : 1;
213	
214	const damagePayout = (damage: Damage, item: Item): number =>
215	  Math.max(0, damage.amount * reimbursementRate(item) - DEDUCTIBLE);
216	
217	/** A policy pays out at most CAP_MULTIPLIER times its insurance sum. */
218	const policyCap = (policy: QuoteStep): number =>
219	  insuranceSum(policy.items) * CAP_MULTIPLIER;
220	
221	const incidentPayout = (incident: Incident, items: Item[]): number =>
222	  roundDown(
223	    incident.damages.reduce(
224	      (total, damage) =>
225	        total +
226	        damagePayout(
227	          damage,
228	          items.find((item) => item.type === damage.itemType) as Item,
229	        ),
230	      0,
231	    ),
232	  );
233	
234	const claimResult = (step: ClaimStep, policy: QuoteStep): ClaimResult => {
235	  const payout = incidentPayout(step.incident, policy.items);
236	
237	  return { payout, remainingCap: policyCap(policy) - payout };
238	};
239	
240	export const runScenario = (scenario: Scenario): ScenarioResults => ({
241	  results: scenario.steps.map((step, index) =>
242	    step.op === "quote"
243	      ? {
244	          premium: quotePremium(
245	            step,
246	            scenario.customer,
247	            isFollowUpContract(scenario.steps.slice(0, index)),
248	          ),
249	        }
250	      : claimResult(step, scenario.steps[step.policy] as QuoteStep),
251	  ),
252	});
